import{_ as t,o as r,c as a,a2 as n}from"./chunks/framework.C7GIOALF.js";const m=JSON.parse('{"title":"Ordinary-Animal Tokens","description":"","frontmatter":{},"headers":[],"relativePath":"research/everyday-life/tokens.md","filePath":"research/everyday-life/tokens.md","lastUpdated":null}'),o={name:"research/everyday-life/tokens.md"};function s(i,e,l,d,c,h){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="ordinary-animal-tokens" tabindex="-1">Ordinary-Animal Tokens <a class="header-anchor" href="#ordinary-animal-tokens" aria-label="Permalink to &quot;Ordinary-Animal Tokens&quot;">​</a></h1><p><strong>Checked October 19, 2026.</strong> There really are Magic tokens named simply <strong>Cat</strong>, <strong>Dog</strong>, <strong>Rat</strong>, <strong>Bird</strong>, <strong>Mouse</strong>, <strong>Squirrel</strong>, and <strong>Bear</strong>. The selected examples below have straightforward animal profiles. A token name does not uniquely specify its colors, size, or abilities.</p><table tabindex="0"><thead><tr><th>Example printing</th><th>Actual type</th><th>Profile</th></tr></thead><tbody><tr><td><a href="https://scryfall.com/card/tfdn/1/cat" target="_blank" rel="noreferrer">Cat — TFDN 1</a></td><td>Token Creature — Cat</td><td>1/1 white; no abilities.</td></tr><tr><td><a href="https://scryfall.com/card/tmkc/15/cat" target="_blank" rel="noreferrer">Cat — TMKC 15</a></td><td>Token Creature — Cat</td><td>2/2 green; no abilities.</td></tr><tr><td><a href="https://scryfall.com/card/tfdn/29/dog" target="_blank" rel="noreferrer">Dog — TFDN 29</a></td><td>Token Creature — Dog</td><td>1/1 white; no abilities.</td></tr><tr><td><a href="https://scryfall.com/card/ttmt/6/rat" target="_blank" rel="noreferrer">Rat — TTMT 6</a></td><td>Token Creature — Rat</td><td>1/1 black; no abilities.</td></tr><tr><td><a href="https://scryfall.com/card/twoe/4/mouse" target="_blank" rel="noreferrer">Mouse — TWOE 4</a></td><td>Token Creature — Mouse</td><td>1/1 white; no abilities.</td></tr><tr><td><a href="https://scryfall.com/card/tblb/23/squirrel" target="_blank" rel="noreferrer">Squirrel — TBLB 23</a></td><td>Token Creature — Squirrel</td><td>1/1 green; no abilities.</td></tr><tr><td><a href="https://scryfall.com/card/thob/7/bear" target="_blank" rel="noreferrer">Bear — THOB 7</a></td><td>Token Creature — Bear</td><td>2/2 green; no abilities.</td></tr><tr><td><a href="https://scryfall.com/card/totj/7/bird" target="_blank" rel="noreferrer">Bird — TOTJ 7</a></td><td>Token Creature — Bird</td><td>1/1 blue; flying.</td></tr></tbody></table><p>Other versions differ. Cats can have lifelink, haste, or even flying; Dogs can be 3/1 with vigilance; Rats can have deathtouch, lifelink, a can&#39;t-block restriction, or a scaling bonus; Birds have several sizes and combat restrictions. Use the token specified by the effect creating it, or the exact profile selected by the box&#39;s written rules. Do not substitute a different profile merely because the name matches.</p><p>These are token components, not ordinary cards to shuffle into a normal deck. A <a href="./../../formats/horde/">Horde</a> may use physical token cards in its library according to its own selected ruleset. That is a format rule, not a general permission to construct a normal Cat deck from token cards.</p><p>For regular creature cards, use the <a href="./animals.html">pet and wildlife catalogue</a> and <a href="./marvel.html#animals">Marvel animals</a>. The complete names and printing links are saved there, including City Pigeon, Lucky the Pizza Dog, Sanctuary Cat, and many others.</p><p>Source: Scryfall records retrieved through the project&#39;s MCP server. <a href="https://scryfall.com/search?q=%28name%3Acat+or+name%3Adog+or+name%3Abird+or+name%3Arat+or+name%3Amouse+or+name%3Asquirrel+or+name%3Abear%29+t%3Atoken+include%3Aextras+unique%3Aprints" target="_blank" rel="noreferrer">Repeat the animal-token search</a>.</p>',7)])])}const u=t(o,[["render",s]]);export{m as __pageData,u as default};
